using AegisCore.Application.Platform;
using AegisCore.Domain;
using AegisCore.Domain.Entities;
using Microsoft.AspNetCore.Mvc;

namespace AegisCore.API.Controllers;

// P119 Fee Defaulter Prediction (extends P103)
[ApiController][Route("api/defaulter-prediction")] public class DefaulterPredictionController : ControllerBase { private IDefaulterPredictionService _s; public DefaulterPredictionController(IDefaulterPredictionService s) => _s = s; [HttpPost("predict/{studentId:guid}")] public async Task<IActionResult> Predict(Guid studentId, [FromQuery] string semester, CancellationToken ct) => Ok(await _s.PredictRiskAsync(studentId, semester, ct)); [HttpGet("scores/{semester}")] public async Task<IActionResult> GetScores(string semester, CancellationToken ct) { var s = await _s.GetRiskScoresBySemesterAsync(semester, ct); return Ok(new { total = s.Count, scores = s }); } [HttpPost("intervene")] public async Task<IActionResult> Intervene([FromQuery] Guid riskScoreId, [FromQuery] Guid studentId, [FromQuery] string tier, CancellationToken ct) { if (!Enum.TryParse<DefaulterRiskTier>(tier, true, out var t)) return BadRequest(); return Ok(await _s.GenerateInterventionAsync(riskScoreId, studentId, t, ct)); } [HttpPost("forecast")] public async Task<IActionResult> Forecast([FromQuery] string semester, CancellationToken ct) => Ok(await _s.GenerateForecastAsync(semester, ct)); [HttpGet("outcomes")] public async Task<IActionResult> Outcomes(CancellationToken ct) { var o = await _s.GetInterventionOutcomesAsync(ct); return Ok(new { total = o.Count, outcomes = o }); } }

// P120 Visiting Faculty Marketplace
[ApiController][Route("api/visiting-faculty")] public class VisitingFacultyController : ControllerBase { private IVisitingFacultyService _s; public VisitingFacultyController(IVisitingFacultyService s) => _s = s; [HttpPost] public async Task<IActionResult> Register([FromBody] VisitingFacultyProfile profile, CancellationToken ct) => Ok(await _s.RegisterFacultyAsync(profile, ct)); [HttpPost("match/{openSlotId:guid}")] public async Task<IActionResult> Match(Guid openSlotId, CancellationToken ct) { var m = await _s.MatchFacultyToSlotsAsync(openSlotId, ct); return Ok(new { total = m.Count, matches = m }); } [HttpPost("contracts")] public async Task<IActionResult> GenerateContract([FromQuery] Guid facultyProfileId, [FromQuery] Guid courseId, CancellationToken ct) => Ok(await _s.GenerateContractAsync(facultyProfileId, courseId, ct)); [HttpGet("eligible")] public async Task<IActionResult> Eligible(CancellationToken ct) { var f = await _s.GetEligibleFacultyAsync(ct); return Ok(new { total = f.Count, faculty = f }); } [HttpPost("contracts/{contractId:guid}/rate")] public async Task<IActionResult> Rate(Guid contractId, [FromQuery] double rating, [FromQuery] string details, CancellationToken ct) { await _s.RateFacultyPerformanceAsync(contractId, rating, details, ct); return Ok(new { message = "Performance rated." }); } }

// P121 Accreditation Readiness Score
[ApiController][Route("api/readiness")] public class ReadinessController : ControllerBase { private IReadinessMeterService _s; public ReadinessController(IReadinessMeterService s) => _s = s; [HttpPost("compute/{frameworkId:guid}")] public async Task<IActionResult> Compute(Guid frameworkId, CancellationToken ct) => Ok(await _s.ComputeScoreAsync(frameworkId, ct)); [HttpGet("{scoreId:guid}/gaps")] public async Task<IActionResult> GetGaps(Guid scoreId, CancellationToken ct) { var g = await _s.GetGapsAsync(scoreId, ct); return Ok(new { total = g.Count, gaps = g }); } [HttpGet("{scoreId:guid}/alerts")] public async Task<IActionResult> GetAlerts(Guid scoreId, CancellationToken ct) { var a = await _s.GetAlertsAsync(scoreId, ct); return Ok(new { total = a.Count, alerts = a }); } [HttpPost("gaps/{gapId:guid}/close")] public async Task<IActionResult> CloseGap(Guid gapId, CancellationToken ct) => Ok(await _s.CloseGapAsync(gapId, ct)); [HttpPost("predict/{frameworkId:guid}")] public async Task<IActionResult> Predict(Guid frameworkId, [FromQuery] DateTime targetDate, CancellationToken ct) => Ok(await _s.PredictReadinessAsync(frameworkId, targetDate, ct)); [HttpPost("check-freshness")] public async Task<IActionResult> CheckFreshness(CancellationToken ct) { await _s.CheckEvidenceFreshnessAsync(ct); return Ok(new { message = "Evidence freshness checked." }); } }

// P122 Student Achievement Gamification
[ApiController][Route("api/achievements")] public class AchievementsController : ControllerBase { private IAchievementService _s; public AchievementsController(IAchievementService s) => _s = s; [HttpPost("detect/{studentId:guid}")] public async Task<IActionResult> Detect(Guid studentId, CancellationToken ct) { var a = await _s.DetectAchievementsAsync(studentId, ct); return Ok(new { total = a.Count, achievements = a }); } [HttpPost("badges")] public async Task<IActionResult> IssueBadge([FromQuery] Guid studentId, [FromQuery] Guid badgeId, [FromQuery] string detail, CancellationToken ct) => Ok(await _s.IssueBadgeAsync(studentId, badgeId, detail, ct)); [HttpPost("deans-list")] public async Task<IActionResult> ProcessDeansList([FromQuery] string semester, CancellationToken ct) { var d = await _s.ProcessDeansListAsync(semester, ct); return Ok(new { total = d.Count, entries = d }); } [HttpPost("leaderboard")] public async Task<IActionResult> Leaderboard([FromQuery] string scope, [FromQuery] string scopeValue, [FromQuery] string semester, CancellationToken ct) { if (!Enum.TryParse<LeaderboardScope>(scope, true, out var s)) return BadRequest(); var l = await _s.GenerateLeaderboardAsync(s, scopeValue, semester, ct); return Ok(new { total = l.Count, entries = l }); } [HttpPost("roadmap/{studentId:guid}")] public async Task<IActionResult> Roadmap(Guid studentId, CancellationToken ct) => Ok(await _s.GenerateRoadmapAsync(studentId, ct)); [HttpGet("catalog")] public async Task<IActionResult> Catalog(CancellationToken ct) { var c = await _s.GetBadgeCatalogAsync(ct); return Ok(new { total = c.Count, badges = c }); } }

// P123 Mental Health Ticketing
[ApiController][Route("api/mental-health")] public class MentalHealthController : ControllerBase { private IMentalHealthService _s; public MentalHealthController(IMentalHealthService s) => _s = s; [HttpPost("tickets")] public async Task<IActionResult> Submit([FromBody] MentalHealthTicket ticket, CancellationToken ct) => Ok(await _s.SubmitTicketAsync(ticket, ct)); [HttpPost("tickets/{id:guid}/classify")] public async Task<IActionResult> Classify(Guid id, CancellationToken ct) { await _s.ClassifyAndRouteAsync(id, ct); return Ok(new { message = "Classified and routed." }); } [HttpPost("tickets/{ticketId:guid}/assign/{counselorId:guid}")] public async Task<IActionResult> Assign(Guid ticketId, Guid counselorId, CancellationToken ct) { await _s.AssignCounselorAsync(ticketId, counselorId, ct); return Ok(new { message = "Assigned." }); } [HttpPost("tickets/{ticketId:guid}/resolve")] public async Task<IActionResult> Resolve(Guid ticketId, [FromQuery] string resolution, CancellationToken ct) { if (!Enum.TryParse<TicketResolution>(resolution, true, out var r)) return BadRequest(); await _s.ResolveTicketAsync(ticketId, r, ct); return Ok(new { message = "Resolved." }); } [HttpPost("tickets/{ticketId:guid}/mandatory-report")] public async Task<IActionResult> MandatoryReport(Guid ticketId, [FromQuery] string trigger, CancellationToken ct) { if (!Enum.TryParse<MandatoryReportTrigger>(trigger, true, out var t)) return BadRequest(); return Ok(await _s.TriggerMandatoryReportAsync(ticketId, t, ct)); } [HttpGet("counselor/{counselorId:guid}/queue")] public async Task<IActionResult> CounselorQueue(Guid counselorId, CancellationToken ct) { var q = await _s.GetCounselorQueueAsync(counselorId, ct); return Ok(new { total = q.Count, tickets = q }); } [HttpPost("tickets/{ticketId:guid}/follow-up")] public async Task<IActionResult> FollowUp(Guid ticketId, [FromQuery] int daysAfter, CancellationToken ct) => Ok(await _s.ScheduleFollowUpAsync(ticketId, daysAfter, ct)); }

