// P125 Voice Assistant (NidaBot)
[ApiController][Route("api/voice")] public class VoiceController : ControllerBase { private IVoiceAssistantService _s; public VoiceController(IVoiceAssistantService s) => _s = s; [HttpPost("audio")] public async Task<IActionResult> ProcessAudio([FromQuery] Guid? userId, CancellationToken ct) { using var reader = new StreamReader(Request.Body); var audio = await reader.ReadToEndAsync(); return Ok(await _s.ProcessAudioAsync(audio, userId, ct)); } [HttpPost("text")] public async Task<IActionResult> ProcessText([FromQuery] Guid? userId, [FromQuery] string language, [FromBody] string text, CancellationToken ct) { if (!Enum.TryParse<VoiceLanguage>(language, true, out var lang)) lang = VoiceLanguage.English; return Ok(await _s.ProcessTextAsync(text, userId, lang, ct)); } [HttpPost("sessions/{id:guid}/execute")] public async Task<IActionResult> Execute(Guid id, CancellationToken ct) => Ok(await _s.ExecuteActionAsync(id, ct)); [HttpGet("sessions/{id:guid}")] public async Task<IActionResult> GetSession(Guid id, CancellationToken ct) => Ok(await _s.GetSessionAsync(id, ct)); }

